    "md_044": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Identity (Entra ID / AD)",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    }
  },
  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"cyc,slot,n\n0,0,7764\n0,1,18258\n0,2,18268\n0,3,17758\n0,4,17895\n0,5,18943\n0,6,7389\n1,0,7474\n1,1,17780\n1,2,18006\n1,3,19161\n1,4,18537\n1,5,17928\n1,6,8120\n2,0,8614\n2,1,17562\n2,2,18440\n2,3,18498\n2,4,18428\n2,5,18299\n2,6,8313\"\n| eval _time=relative_time(now(), \"@w0\") + slot*86400 - cyc*604800\n| where _time<=now() AND _time>now()-1209600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,pct\n13,99.95\n12,99.98\n11,99.94\n10,99.94\n9,99.97\n8,99.96\n7,99.95\n6,99.94\n5,99.98\n4,99.97\n3,99.96\n2,99.91\n1,99.97\n0,99.94\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time pct",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"cyc,slot,n\n0,0,1397\n0,1,3217\n0,2,3093\n0,3,2955\n0,4,3238\n0,5,2929\n0,6,1373\n1,0,1320\n1,1,3253\n1,2,2944\n1,3,3154\n1,4,3232\n1,5,3164\n1,6,1306\n2,0,1497\n2,1,2972\n2,2,3210\n2,3,2932\n2,4,3176\n2,5,2919\n2,6,1450\"\n| eval _time=relative_time(now(), \"@w0\") + slot*86400 - cyc*604800\n| where _time<=now() AND _time>now()-1209600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
