    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,4\n12,4\n11,5\n10,3\n9,3\n8,3\n7,2\n6,2\n5,3\n4,2\n3,2\n2,1\n1,2\n0,2\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_023": {
      "type": "ds.search",
      "name": "ds_023",
